scripts.iterate_map:
def solve(inputs: dict) -> float:
    x = int(inputs['X'])
    c = int(inputs['C'])
    mod = int(inputs['MOD'])
    k = int(inputs['K'])

    for step in range(k):
        x = (x * x + c) % mod
        print(f"Step {step + 1}: x = {x}")

    return float(x)

