def solve(inputs: dict) -> float:
    s = int(inputs['SEED'])
    a = int(inputs['A'])
    b = int(inputs['B'])
    m = int(inputs['M'])
    k = int(inputs['K'])

    for step in range(k):
        s = (a * s + b) % m
        print(f"Step {step + 1}: s = {s}")

    return float(s)

